import math
from typing import Any


def _is_integer(value):
    # bool is a subclass of int in Python, so reject it explicitly.
    return isinstance(value, int) and not isinstance(value, bool)


def _is_text(value):
    return isinstance(value, str)


def _is_mapping(value):
    return isinstance(value, dict)


def _reject_non_finite(value):
    """Recursively reject NaN/Infinity anywhere in the input.

    The task requires that nested JSON values be legal even in fields that
    are not used by this component.
    """
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("non-finite JSON number is not allowed")
    elif isinstance(value, dict):
        for item in value.values():
            _reject_non_finite(item)
    elif isinstance(value, list):
        for item in value:
            _reject_non_finite(item)


def _unwrap_payload(payload):
    """Return result for a component envelope, otherwise return payload."""
    if (
        _is_mapping(payload)
        and set(payload.keys()) == {"name", "result"}
        and _is_text(payload.get("name"))
        and isinstance(payload.get("result"), (dict, list))
    ):
        return payload["result"]
    return payload


def _require_keys(mapping, required, label):
    if not _is_mapping(mapping):
        raise ValueError(f"{label} must be an object")
    missing = [key for key in required if key not in mapping]
    if missing:
        raise ValueError(f"{label} missing field(s): {', '.join(missing)}")


